export const EXTRA_PRAYER_VERSES: BibleVerse[] = [
  { id: "faith-5", category: "faith", reference: "Romans 1:17", text: "For therein is the righteousness of God revealed from faith to faith: as it is written, The just shall live by faith." },
  { id: "faith-6", category: "faith", reference: "Romans 4:20-21", text: "He staggered not at the promise of God through unbelief; but was strong in faith, giving glory to God; And being fully persuaded that, what he had promised, he was able also to perform." },
  { id: "faith-7", category: "faith", reference: "Romans 5:1", text: "Therefore being justified by faith, we have peace with God through our Lord Jesus Christ:" },
  { id: "faith-8", category: "faith", reference: "Romans 10:9-10", text: "That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved. For with the heart man believeth unto righteousness; and with the mouth confession is made unto salvation." },
  { id: "faith-9", category: "faith", reference: "Romans 12:3", text: "For I say, through the grace given unto me, to every man that is among you, not to think of himself more highly than he ought to think; but to think soberly, according as God hath dealt to every man the measure of faith." },
  { id: "faith-10", category: "faith", reference: "Romans 8:24-25", text: "For we are saved by hope: but hope that is seen is not hope: for what a man seeth, why doth he yet hope for? But if we hope for that we see not, then do we with patience wait for it." },
  { id: "faith-11", category: "faith", reference: "2 Corinthians 5:7", text: "(For we walk by faith, not by sight:)" },
  { id: "faith-12", category: "faith", reference: "2 Corinthians 4:18", text: "While we look not at the things which are seen, but at the things which are not seen: for the things which are seen are temporal; but the things which are not seen are eternal." },
  { id: "faith-13", category: "faith", reference: "Galatians 2:20", text: "I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me." },
  { id: "faith-14", category: "faith", reference: "Galatians 3:26", text: "For ye are all the children of God by faith in Christ Jesus." },
  { id: "faith-15", category: "faith", reference: "Ephesians 2:8-9", text: "For by grace are ye saved through faith; and that not of yourselves: it is the gift of God: Not of works, lest any man should boast." },
  { id: "faith-16", category: "faith", reference: "Ephesians 6:16", text: "Above all, taking the shield of faith, wherewith ye shall be able to quench all the fiery darts of the wicked." },
  { id: "faith-17", category: "faith", reference: "1 John 5:4", text: "For whatsoever is born of God overcometh the world: and this is the victory that overcometh the world, even our faith." },
  { id: "faith-18", category: "faith", reference: "Matthew 9:29", text: "Then touched he their eyes, saying, According to your faith be it unto you." },
  { id: "faith-19", category: "faith", reference: "Matthew 17:20", text: "And Jesus said unto them, Because of your unbelief: for verily I say unto you, If ye have faith as a grain of mustard seed, ye shall say unto this mountain, Remove hence to yonder place; and it shall remove; and nothing shall be impossible unto you." },
  { id: "faith-20", category: "faith", reference: "Matthew 21:21-22", text: "Jesus answered and said unto them, Verily I say unto you, If ye have faith, and doubt not, ye shall not only do this which is done to the fig tree, but also if ye shall say unto this mountain, Be thou removed, and be thou cast into the sea; it shall be done. And all things, whatsoever ye shall ask in prayer, believing, ye shall receive." },
  { id: "faith-21", category: "faith", reference: "Matthew 8:10", text: "When Jesus heard it, he marvelled, and said to them that followed, Verily I say unto you, I have not found so great faith, no, not in Israel." },
  { id: "faith-22", category: "faith", reference: "Matthew 15:28", text: "Then Jesus answered and said unto her, O woman, great is thy faith: be it unto thee even as thou wilt. And her daughter was made whole from that very hour." },
  { id: "faith-23", category: "faith", reference: "Matthew 6:30", text: "Wherefore, if God so clothe the grass of the field, which to day is, and to morrow is cast into the oven, shall he not much more clothe you, O ye of little faith?" },
  { id: "faith-24", category: "faith", reference: "Mark 9:23", text: "Jesus said unto him, If thou canst believe, all things are possible to him that believeth." },
  { id: "faith-25", category: "faith", reference: "Mark 5:36", text: "As soon as Jesus heard the word that was spoken, he saith unto the ruler of the synagogue, Be not afraid, only believe." },
  { id: "faith-26", category: "faith", reference: "Mark 10:52", text: "And Jesus said unto him, Go thy way; thy faith hath made thee whole. And immediately he received his sight, and followed Jesus in the way." },
  { id: "faith-27", category: "faith", reference: "Mark 11:22-23", text: "And Jesus answering saith unto them, Have faith in God. For verily I say unto you, That whosoever shall say unto this mountain, Be thou removed, and be thou cast into the sea; and shall not doubt in his heart, but shall believe that those things which he saith shall come to pass; he shall have whatsoever he saith." },
  { id: "faith-28", category: "faith", reference: "Luke 17:5-6", text: "And the apostles said unto the Lord, Increase our faith. And the Lord said, If ye had faith as a grain of mustard seed, ye might say unto this sycamine tree, Be thou plucked up by the root, and be thou planted in the sea; and it should obey you." },
  { id: "faith-29", category: "faith", reference: "Luke 1:37", text: "For with God nothing shall be impossible." },
  { id: "faith-30", category: "faith", reference: "Luke 1:45", text: "And blessed is she that believed: for there shall be a performance of those things which were told her from the Lord." },
  { id: "faith-31", category: "faith", reference: "Luke 7:50", text: "And he said to the woman, Thy faith hath saved thee; go in peace." },
  { id: "faith-32", category: "faith", reference: "John 20:29", text: "Jesus saith unto him, Thomas, because thou hast seen me, thou hast believed: blessed are they that have not seen, and yet have believed." },
  { id: "faith-33", category: "faith", reference: "John 3:16", text: "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life." },
  { id: "faith-34", category: "faith", reference: "John 11:25-26", text: "Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live: And whosoever liveth and believeth in me shall never die. Believest thou this?" },
  { id: "faith-35", category: "faith", reference: "Hebrews 10:23", text: "Let us hold fast the profession of our faith without wavering; (for he is faithful that promised;)" },
  { id: "faith-36", category: "faith", reference: "Hebrews 10:38", text: "Now the just shall live by faith: but if any man draw back, my soul shall have no pleasure in him." },
  { id: "faith-37", category: "faith", reference: "Hebrews 12:2", text: "Looking unto Jesus the author and finisher of our faith; who for the joy that was set before him endured the cross, despising the shame, and is set down at the right hand of the throne of God." },
  { id: "faith-38", category: "faith", reference: "Hebrews 11:8", text: "By faith Abraham, when he was called to go out into a place which he should after receive for an inheritance, obeyed; and he went out, not knowing whither he went." },
  { id: "faith-39", category: "faith", reference: "Hebrews 11:7", text: "By faith Noah, being warned of God of things not seen as yet, moved with fear, prepared an ark to the saving of his house; by the which he condemned the world, and became heir of the righteousness which is by faith." },
  { id: "faith-40", category: "faith", reference: "James 2:17", text: "Even so faith, if it hath not works, is dead, being alone." },
  { id: "faith-41", category: "faith", reference: "James 2:26", text: "For as the body without the spirit is dead, so faith without works is dead also." },
  { id: "faith-42", category: "faith", reference: "James 1:6", text: "But let him ask in faith, nothing wavering. For he that wavereth is like a wave of the sea driven with the wind and tossed." },
  { id: "faith-43", category: "faith", reference: "1 Peter 1:7", text: "That the trial of your faith, being much more precious than of gold that perisheth, though it be tried with fire, might be found unto praise and honour and glory at the appearing of Jesus Christ:" },
  { id: "faith-44", category: "faith", reference: "1 Peter 1:8-9", text: "Whom having not seen, ye love; in whom, though now ye see him not, yet believing, ye rejoice with joy unspeakable and full of glory: Receiving the end of your faith, even the salvation of your souls." },
  { id: "faith-45", category: "faith", reference: "2 Timothy 1:12", text: "For the which cause I also suffer these things: nevertheless I am not ashamed: for I know whom I have believed, and am persuaded that he is able to keep that which I have committed unto him against that day." },
  { id: "faith-46", category: "faith", reference: "2 Timothy 4:7", text: "I have fought a good fight, I have finished my course, I have kept the faith:" },
  { id: "faith-47", category: "faith", reference: "1 Timothy 6:12", text: "Fight the good fight of faith, lay hold on eternal life, whereunto thou art also called, and hast professed a good profession before many witnesses." },
  { id: "faith-48", category: "faith", reference: "Habakkuk 2:4", text: "Behold, his soul which is lifted up is not upright in him: but the just shall live by his faith." },
  { id: "faith-49", category: "faith", reference: "Genesis 15:6", text: "And he believed in the Lord; and he counted it to him for righteousness." },
  { id: "faith-50", category: "faith", reference: "Psalm 56:3", text: "What time I am afraid, I will trust in thee." },
  { id: "protection-6", category: "protection", reference: "Psalm 91:2", text: "I will say of the Lord, He is my refuge and my fortress: my God; in him will I trust." },
  { id: "protection-7", category: "protection", reference: "Psalm 91:3-4", text: "Surely he shall deliver thee from the snare of the fowler, and from the noisome pestilence. He shall cover thee with his feathers, and under his wings shalt thou trust: his truth shall be thy shield and buckler." },
  { id: "protection-8", category: "protection", reference: "Psalm 91:5-6", text: "Thou shalt not be afraid for the terror by night; nor for the arrow that flieth by day; Nor for the pestilence that walketh in darkness; nor for the destruction that wasteth at noonday." },
  { id: "protection-9", category: "protection", reference: "Psalm 91:7", text: "A thousand shall fall at thy side, and ten thousand at thy right hand; but it shall not come nigh thee." },
  { id: "protection-10", category: "protection", reference: "Psalm 91:9-10", text: "Because thou hast made the Lord, which is my refuge, even the most High, thy habitation; There shall no evil befall thee, neither shall any plague come nigh thy dwelling." },
  { id: "protection-11", category: "protection", reference: "Psalm 91:14-16", text: "Because he hath set his love upon me, therefore will I deliver him: I will set him on high, because he hath known my name. He shall call upon me, and I will answer him: I will be with him in trouble; I will deliver him, and honour him. With long life will I satisfy him, and shew him my salvation." },
  { id: "protection-12", category: "protection", reference: "Psalm 121:1-2", text: "I will lift up mine eyes unto the hills, from whence cometh my help. My help cometh from the Lord, which made heaven and earth." },
  { id: "protection-13", category: "protection", reference: "Psalm 121:3", text: "He will not suffer thy foot to be moved: he that keepeth thee will not slumber." },
  { id: "protection-14", category: "protection", reference: "Psalm 27:1", text: "The Lord is my light and my salvation; whom shall I fear? the Lord is the strength of my life; of whom shall I be afraid?" },
  { id: "protection-15", category: "protection", reference: "Psalm 27:5", text: "For in the time of trouble he shall hide me in his pavilion: in the secret of his tabernacle shall he hide me; he shall set me up upon a rock." },
  { id: "protection-16", category: "protection", reference: "Psalm 23:4", text: "Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me." },
  { id: "protection-17", category: "protection", reference: "Psalm 34:7", text: "The angel of the Lord encampeth round about them that fear him, and delivereth them." },
  { id: "protection-18", category: "protection", reference: "Psalm 34:19", text: "Many are the afflictions of the righteous: but the Lord delivereth him out of them all." },
  { id: "protection-19", category: "protection", reference: "Psalm 18:2", text: "The Lord is my rock, and my fortress, and my deliverer; my God, my strength, in whom I will trust; my buckler, and the horn of my salvation, and my high tower." },
  { id: "protection-20", category: "protection", reference: "Psalm 18:30", text: "As for God, his way is perfect: the word of the Lord is tried: he is a buckler to all those that trust in him." },
  { id: "protection-21", category: "protection", reference: "Psalm 32:7", text: "Thou art my hiding place; thou shalt preserve me from trouble; thou shalt compass me about with songs of deliverance. Selah." },
  { id: "protection-22", category: "protection", reference: "Psalm 61:3", text: "For thou hast been a shelter for me, and a strong tower from the enemy." },
  { id: "protection-23", category: "protection", reference: "Psalm 62:6-7", text: "He only is my rock and my salvation: he is my defence; I shall not be moved. In God is my salvation and my glory: the rock of my strength, and my refuge, is in God." },
  { id: "protection-24", category: "protection", reference: "Psalm 3:3", text: "But thou, O Lord, art a shield for me; my glory, and the lifter up of mine head." },
  { id: "protection-25", category: "protection", reference: "Psalm 4:8", text: "I will both lay me down in peace, and sleep: for thou, Lord, only makest me dwell in safety." },
  { id: "protection-26", category: "protection", reference: "Psalm 5:11", text: "But let all those that put their trust in thee rejoice: let them ever shout for joy, because thou defendest them: let them also that love thy name be joyful in thee." },
  { id: "protection-27", category: "protection", reference: "Psalm 9:9", text: "The Lord also will be a refuge for the oppressed, a refuge in times of trouble." },
  { id: "protection-28", category: "protection", reference: "Psalm 57:1", text: "Be merciful unto me, O God, be merciful unto me: for my soul trusteth in thee: yea, in the shadow of thy wings will I make my refuge, until these calamities be overpast." },
  { id: "protection-29", category: "protection", reference: "Psalm 62:2", text: "He only is my rock and my salvation; he is my defence; I shall not be greatly moved." },
  { id: "protection-30", category: "protection", reference: "Psalm 125:2", text: "As the mountains are round about Jerusalem, so the Lord is round about his people from henceforth even for ever." },
  { id: "protection-31", category: "protection", reference: "Psalm 138:7", text: "Though I walk in the midst of trouble, thou wilt revive me: thou shalt stretch forth thine hand against the wrath of mine enemies, and thy right hand shall save me." },
  { id: "protection-32", category: "protection", reference: "Psalm 144:2", text: "My goodness, and my fortress; my high tower, and my deliverer; my shield, and he in whom I trust; who subdueth my people under me." },
  { id: "protection-33", category: "protection", reference: "Psalm 20:1", text: "The Lord hear thee in the day of trouble; the name of the God of Jacob defend thee;" },
  { id: "protection-34", category: "protection", reference: "Proverbs 1:33", text: "But whoso hearkeneth unto me shall dwell safely, and shall be quiet from fear of evil." },
  { id: "protection-35", category: "protection", reference: "Proverbs 3:25-26", text: "Be not afraid of sudden fear, neither of the desolation of the wicked, when it cometh. For the Lord shall be thy confidence, and shall keep thy foot from being taken." },
  { id: "protection-36", category: "protection", reference: "Proverbs 29:25", text: "The fear of man bringeth a snare: but whoso putteth his trust in the Lord shall be safe." },
  { id: "protection-37", category: "protection", reference: "Isaiah 54:17", text: "No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the Lord, and their righteousness is of me, saith the Lord." },
  { id: "protection-38", category: "protection", reference: "Isaiah 59:19", text: "So shall they fear the name of the Lord from the west, and his glory from the rising of the sun. When the enemy shall come in like a flood, the Spirit of the Lord shall lift up a standard against him." },
  { id: "protection-39", category: "protection", reference: "Isaiah 12:2", text: "Behold, God is my salvation; I will trust, and not be afraid: for the Lord Jehovah is my strength and my song; he also is become my salvation." },
  { id: "protection-40", category: "protection", reference: "Nahum 1:7", text: "The Lord is good, a strong hold in the day of trouble; and he knoweth them that trust in him." },
  { id: "protection-41", category: "protection", reference: "Deuteronomy 31:6", text: "Be strong and of a good courage, fear not, nor be afraid of them: for the Lord thy God, he it is that doth go with thee; he will not fail thee, nor forsake thee." },
  { id: "protection-42", category: "protection", reference: "Deuteronomy 33:27", text: "The eternal God is thy refuge, and underneath are the everlasting arms: and he shall thrust out the enemy from before thee; and shall say, Destroy them." },
  { id: "protection-43", category: "protection", reference: "Deuteronomy 20:4", text: "For the Lord your God is he that goeth with you, to fight for you against your enemies, to save you." },
  { id: "protection-44", category: "protection", reference: "Exodus 14:14", text: "The Lord shall fight for you, and ye shall hold your peace." },
  { id: "protection-45", category: "protection", reference: "2 Samuel 22:3", text: "The God of my rock; in him will I trust: he is my shield, and the horn of my salvation, my high tower, and my refuge, my saviour; thou savest me from violence." },
  { id: "protection-46", category: "protection", reference: "2 Kings 6:16", text: "And he answered, Fear not: for they that be with us are more than they that be with them." },
  { id: "protection-47", category: "protection", reference: "Zechariah 2:5", text: "For I, saith the Lord, will be unto her a wall of fire round about, and will be the glory in the midst of her." },
  { id: "protection-48", category: "protection", reference: "Luke 10:19", text: "Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy: and nothing shall by any means hurt you." },
  { id: "protection-49", category: "protection", reference: "Romans 8:31", text: "What shall we then say to these things? If God be for us, who can be against us?" },
  { id: "protection-50", category: "protection", reference: "Romans 8:38-39", text: "For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor powers, nor things present, nor things to come, Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord." },
  { id: "healing-6", category: "healing", reference: "Psalm 147:3", text: "He healeth the broken in heart, and bindeth up their wounds." },
  { id: "healing-7", category: "healing", reference: "Psalm 107:20", text: "He sent his word, and healed them, and delivered them from their destructions." },
  { id: "healing-8", category: "healing", reference: "Psalm 30:2", text: "O Lord my God, I cried unto thee, and thou hast healed me." },
  { id: "healing-9", category: "healing", reference: "Psalm 41:3", text: "The Lord will strengthen him upon the bed of languishing: thou wilt make all his bed in his sickness." },
  { id: "healing-10", category: "healing", reference: "Psalm 6:2", text: "Have mercy upon me, O Lord; for I am weak: O Lord, heal me; for my bones are vexed." },
  { id: "healing-11", category: "healing", reference: "Exodus 23:25", text: "And ye shall serve the Lord your God, and he shall bless thy bread, and thy water; and I will take sickness away from the midst of thee." },
  { id: "healing-12", category: "healing", reference: "Deuteronomy 7:15", text: "And the Lord will take away from thee all sickness, and will put none of the evil diseases of Egypt, which thou knowest, upon thee; but will lay them upon all them that hate thee." },
  { id: "healing-13", category: "healing", reference: "Deuteronomy 32:39", text: "See now that I, even I, am he, and there is no god with me: I kill, and I make alive; I wound, and I heal: neither is there any that can deliver out of my hand." },
  { id: "healing-14", category: "healing", reference: "2 Kings 20:5", text: "Turn again, and tell Hezekiah the captain of my people, Thus saith the Lord, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will heal thee: on the third day thou shalt go up unto the house of the Lord." },
  { id: "healing-15", category: "healing", reference: "Jeremiah 30:17", text: "For I will restore health unto thee, and I will heal thee of thy wounds, saith the Lord; because they called thee an Outcast, saying, This is Zion, whom no man seeketh after." },
  { id: "healing-16", category: "healing", reference: "Jeremiah 33:6", text: "Behold, I will bring it health and cure, and I will cure them, and will reveal unto them the abundance of peace and truth." },
  { id: "healing-17", category: "healing", reference: "Malachi 4:2", text: "But unto you that fear my name shall the Sun of righteousness arise with healing in his wings; and ye shall go forth, and grow up as calves of the stall." },
  { id: "healing-18", category: "healing", reference: "Isaiah 58:8", text: "Then shall thy light break forth as the morning, and thine health shall spring forth speedily: and thy righteousness shall go before thee; the glory of the Lord shall be thy reward." },
  { id: "healing-19", category: "healing", reference: "Isaiah 57:18-19", text: "I have seen his ways, and will heal him: I will lead him also, and restore comforts unto him and to his mourners. I create the fruit of the lips; Peace, peace to him that is far off, and to him that is near, saith the Lord; and I will heal him." },
  { id: "healing-20", category: "healing", reference: "Isaiah 33:24", text: "And the inhabitant shall not say, I am sick: the people that dwell therein shall be forgiven their iniquity." },
  { id: "healing-21", category: "healing", reference: "Proverbs 4:20-22", text: "My son, attend to my words; incline thine ear unto my sayings. Let them not depart from thine eyes; keep them in the midst of thine heart. For they are life unto those that find them, and health to all their flesh." },
  { id: "healing-22", category: "healing", reference: "Proverbs 3:7-8", text: "Be not wise in thine own eyes: fear the Lord, and depart from evil. It shall be health to thy navel, and marrow to thy bones." },
  { id: "healing-23", category: "healing", reference: "Proverbs 16:24", text: "Pleasant words are as an honeycomb, sweet to the soul, and health to the bones." },
  { id: "healing-24", category: "healing", reference: "Proverbs 17:22", text: "A merry heart doeth good like a medicine: but a broken spirit drieth the bones." },
  { id: "healing-25", category: "healing", reference: "Proverbs 12:18", text: "There is that speaketh like the piercings of a sword: but the tongue of the wise is health." },
  { id: "healing-26", category: "healing", reference: "Matthew 8:17", text: "That it might be fulfilled which was spoken by Esaias the prophet, saying, Himself took our infirmities, and bare our sicknesses." },
  { id: "healing-27", category: "healing", reference: "Matthew 9:22", text: "But Jesus turned him about, and when he saw her, he said, Daughter, be of good comfort; thy faith hath made thee whole. And the woman was made whole from that hour." },
  { id: "healing-28", category: "healing", reference: "Matthew 4:23", text: "And Jesus went about all Galilee, teaching in their synagogues, and preaching the gospel of the kingdom, and healing all manner of sickness and all manner of disease among the people." },
  { id: "healing-29", category: "healing", reference: "Matthew 10:1", text: "And when he had called unto him his twelve disciples, he gave them power against unclean spirits, to cast them out, and to heal all manner of sickness and all manner of disease." },
  { id: "healing-30", category: "healing", reference: "Matthew 8:3", text: "And Jesus put forth his hand, and touched him, saying, I will; be thou clean. And immediately his leprosy was cleansed." },
  { id: "healing-31", category: "healing", reference: "Matthew 8:8", text: "The centurion answered and said, Lord, I am not worthy that thou shouldest come under my roof: but speak the word only, and my servant shall be healed." },
  { id: "healing-32", category: "healing", reference: "Mark 5:34", text: "And he said unto her, Daughter, thy faith hath made thee whole; go in peace, and be whole of thy plague." },
  { id: "healing-33", category: "healing", reference: "Mark 16:17-18", text: "And these signs shall follow them that believe; In my name shall they cast out devils; they shall speak with new tongues; They shall take up serpents; and if they drink any deadly thing, it shall not hurt them; they shall lay hands on the sick, and they shall recover." },
  { id: "healing-34", category: "healing", reference: "Luke 6:19", text: "And the whole multitude sought to touch him: for there went virtue out of him, and healed them all." },
  { id: "healing-35", category: "healing", reference: "Luke 9:11", text: "And the people, when they knew it, followed him: and he received them, and spake unto them of the kingdom of God, and healed them that had need of healing." },
  { id: "healing-36", category: "healing", reference: "Luke 8:48", text: "And he said unto her, Daughter, be of good comfort: thy faith hath made thee whole; go in peace." },
  { id: "healing-37", category: "healing", reference: "Luke 4:18", text: "The Spirit of the Lord is upon me, because he hath anointed me to preach the gospel to the poor; he hath sent me to heal the brokenhearted, to preach deliverance to the captives, and recovering of sight to the blind, to set at liberty them that are bruised," },
  { id: "healing-38", category: "healing", reference: "Acts 10:38", text: "How God anointed Jesus of Nazareth with the Holy Ghost and with power: who went about doing good, and healing all that were oppressed of the devil; for God was with him." },
  { id: "healing-39", category: "healing", reference: "Acts 5:16", text: "There came also a multitude out of the cities round about unto Jerusalem, bringing sick folks, and them which were vexed with unclean spirits: and they were healed every one." },
  { id: "healing-40", category: "healing", reference: "1 Peter 2:24", text: "Who his own self bare our sins in his own body on the tree, that we, being dead to sins, should live unto righteousness: by whose stripes ye were healed." },
  { id: "healing-41", category: "healing", reference: "3 John 1:2", text: "Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth." },
  { id: "healing-42", category: "healing", reference: "Romans 8:11", text: "But if the Spirit of him that raised up Jesus from the dead dwell in you, he that raised up Christ from the dead shall also quicken your mortal bodies by his Spirit that dwelleth in you." },
  { id: "healing-43", category: "healing", reference: "Hebrews 13:8", text: "Jesus Christ the same yesterday, and to day, and for ever." },
  { id: "healing-44", category: "healing", reference: "Job 5:18", text: "For he maketh sore, and bindeth up: he woundeth, and his hands make whole." },
  { id: "healing-45", category: "healing", reference: "2 Corinthians 12:9", text: "And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me." },
  { id: "healing-46", category: "healing", reference: "Revelation 21:4", text: "And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away." },
  { id: "healing-47", category: "healing", reference: "Psalm 118:17", text: "I shall not die, but live, and declare the works of the Lord." },
  { id: "healing-48", category: "healing", reference: "Psalm 103:3-5", text: "Who forgiveth all thine iniquities; who healeth all thy diseases; Who redeemeth thy life from destruction; who crowneth thee with lovingkindness and tender mercies; Who satisfieth thy mouth with good things; so that thy youth is renewed like the eagle's." },
  { id: "healing-49", category: "healing", reference: "2 Chronicles 7:14", text: "If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land." },
  { id: "healing-50", category: "healing", reference: "Isaiah 61:1", text: "The Spirit of the Lord God is upon me; because the Lord hath anointed me to preach good tidings unto the meek; he hath sent me to bind up the brokenhearted, to proclaim liberty to the captives, and the opening of the prison to them that are bound;" },
  { id: "strength-5", category: "strength", reference: "Exodus 15:2", text: "The Lord is my strength and song, and he is become my salvation: he is my God, and I will prepare him an habitation; my father's God, and I will exalt him." },
  { id: "strength-6", category: "strength", reference: "Joshua 1:9", text: "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the Lord thy God is with thee whithersoever thou goest." },
  { id: "strength-7", category: "strength", reference: "Nehemiah 8:10", text: "Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the Lord is your strength." },
  { id: "strength-8", category: "strength", reference: "1 Chronicles 16:11", text: "Seek the Lord and his strength, seek his face continually." },
  { id: "strength-9", category: "strength", reference: "1 Chronicles 29:12", text: "Both riches and honour come of thee, and thou reignest over all; and in thine hand is power and might; and in thine hand it is to make great, and to give strength unto all." },
  { id: "strength-10", category: "strength", reference: "2 Chronicles 16:9", text: "For the eyes of the Lord run to and fro throughout the whole earth, to shew himself strong in the behalf of them whose heart is perfect toward him. Herein thou hast done foolishly: therefore from henceforth thou shalt have wars." },
  { id: "strength-11", category: "strength", reference: "Psalm 18:32", text: "It is God that girdeth me with strength, and maketh my way perfect." },
  { id: "strength-12", category: "strength", reference: "Psalm 18:1", text: "I will love thee, O Lord, my strength." },
  { id: "strength-13", category: "strength", reference: "Psalm 27:14", text: "Wait on the Lord: be of good courage, and he shall strengthen thine heart: wait, I say, on the Lord." },
  { id: "strength-14", category: "strength", reference: "Psalm 29:11", text: "The Lord will give strength unto his people; the Lord will bless his people with peace." },
  { id: "strength-15", category: "strength", reference: "Psalm 31:24", text: "Be of good courage, and he shall strengthen your heart, all ye that hope in the Lord." },
  { id: "strength-16", category: "strength", reference: "Psalm 68:35", text: "O God, thou art terrible out of thy holy places: the God of Israel is he that giveth strength and power unto his people. Blessed be God." },
  { id: "strength-17", category: "strength", reference: "Psalm 73:26", text: "My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever." },
  { id: "strength-18", category: "strength", reference: "Psalm 119:28", text: "My soul melteth for heaviness: strengthen thou me according unto thy word." },
  { id: "strength-19", category: "strength", reference: "Psalm 138:3", text: "In the day when I cried thou answeredst me, and strengthenedst me with strength in my soul." },
  { id: "strength-20", category: "strength", reference: "Psalm 84:5-7", text: "Blessed is the man whose strength is in thee; in whose heart are the ways of them. Who passing through the valley of Baca make it a well; the rain also filleth the pools. They go from strength to strength, every one of them in Zion appeareth before God." },
  { id: "strength-21", category: "strength", reference: "Isaiah 40:29", text: "He giveth power to the faint; and to them that have no might he increaseth strength." },
  { id: "strength-22", category: "strength", reference: "Isaiah 41:13", text: "For I the Lord thy God will hold thy right hand, saying unto thee, Fear not; I will help thee." },
  { id: "strength-23", category: "strength", reference: "Isaiah 30:15", text: "For thus saith the Lord God, the Holy One of Israel; In returning and rest shall ye be saved; in quietness and in confidence shall be your strength: and ye would not." },
  { id: "strength-24", category: "strength", reference: "Habakkuk 3:19", text: "The Lord God is my strength, and he will make my feet like hinds' feet, and he will make me to walk upon mine high places. To the chief singer on my stringed instruments." },
  { id: "strength-25", category: "strength", reference: "Zechariah 4:6", text: "Then he answered and spake unto me, saying, This is the word of the Lord unto Zerubbabel, saying, Not by might, nor by power, but by my spirit, saith the Lord of hosts." },
  { id: "strength-26", category: "strength", reference: "Ephesians 3:16", text: "That he would grant you, according to the riches of his glory, to be strengthened with might by his Spirit in the inner man;" },
  { id: "strength-27", category: "strength", reference: "Ephesians 6:10", text: "Finally, my brethren, be strong in the Lord, and in the power of his might." },
  { id: "strength-28", category: "strength", reference: "2 Corinthians 12:9-10", text: "And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me. Therefore I take pleasure in infirmities, in reproaches, in necessities, in persecutions, in distresses for Christ's sake: for when I am weak, then am I strong." },
  { id: "strength-29", category: "strength", reference: "2 Corinthians 4:16", text: "For which cause we faint not; but though our outward man perish, yet the inward man is renewed day by day." },
  { id: "strength-30", category: "strength", reference: "Colossians 1:11", text: "Strengthened with all might, according to his glorious power, unto all patience and longsuffering with joyfulness;" },
  { id: "strength-31", category: "strength", reference: "2 Timothy 1:7", text: "For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind." },
  { id: "strength-32", category: "strength", reference: "2 Timothy 4:17", text: "Notwithstanding the Lord stood with me, and strengthened me; that by me the preaching might be fully known, and that all the Gentiles might hear: and I was delivered out of the mouth of the lion." },
  { id: "strength-33", category: "strength", reference: "Galatians 6:9", text: "And let us not be weary in well doing: for in due season we shall reap, if we faint not." },
  { id: "strength-34", category: "strength", reference: "Hebrews 12:1", text: "Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us," },
  { id: "strength-35", category: "strength", reference: "Romans 8:37", text: "Nay, in all these things we are more than conquerors through him that loved us." },
  { id: "strength-36", category: "strength", reference: "1 Corinthians 15:58", text: "Therefore, my beloved brethren, be ye stedfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord." },
  { id: "strength-37", category: "strength", reference: "1 Corinthians 16:13", text: "Watch ye, stand fast in the faith, quit you like men, be strong." },
  { id: "strength-38", category: "strength", reference: "1 Corinthians 10:13", text: "There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able; but will with the temptation also make a way to escape, that ye may be able to bear it." },
  { id: "strength-39", category: "strength", reference: "2 Samuel 22:33", text: "God is my strength and power: and he maketh my way perfect." },
  { id: "strength-40", category: "strength", reference: "2 Samuel 22:40", text: "For thou hast girded me with strength to battle: them that rose up against me hast thou subdued under me." },
  { id: "strength-41", category: "strength", reference: "Job 17:9", text: "The righteous also shall hold on his way, and he that hath clean hands shall be stronger and stronger." },
  { id: "strength-42", category: "strength", reference: "Proverbs 24:10", text: "If thou faint in the day of adversity, thy strength is small." },
  { id: "strength-43", category: "strength", reference: "Proverbs 24:16", text: "For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief." },
  { id: "strength-44", category: "strength", reference: "Micah 7:8", text: "Rejoice not against me, O mine enemy: when I fall, I shall arise; when I sit in darkness, the Lord shall be a light unto me." },
  { id: "strength-45", category: "strength", reference: "John 15:5", text: "I am the vine, ye are the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing." },
  { id: "strength-46", category: "strength", reference: "Matthew 11:28-30", text: "Come unto me, all ye that labour and are heavy laden, and I will give you rest. Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls. For my yoke is easy, and my burden is light." },
  { id: "strength-47", category: "strength", reference: "Deuteronomy 33:25", text: "Thy shoes shall be iron and brass; and as thy days, so shall thy strength be." },
  { id: "strength-48", category: "strength", reference: "Deuteronomy 31:8", text: "And the Lord, he it is that doth go before thee; he will be with thee, he will not fail thee, neither forsake thee: fear not, neither be dismayed." },
  { id: "strength-49", category: "strength", reference: "Psalm 59:16", text: "But I will sing of thy power; yea, I will sing aloud of thy mercy in the morning: for thou hast been my defence and refuge in the day of my trouble." },
  { id: "strength-50", category: "strength", reference: "Psalm 119:116", text: "Uphold me according unto thy word, that I may live: and let me not be ashamed of my hope." },
  { id: "peace-6", category: "peace", reference: "Numbers 6:24-26", text: "The Lord bless thee, and keep thee: The Lord make his face shine upon thee, and be gracious unto thee: The Lord lift up his countenance upon thee, and give thee peace." },
  { id: "peace-7", category: "peace", reference: "Psalm 34:14", text: "Depart from evil, and do good; seek peace, and pursue it." },
  { id: "peace-8", category: "peace", reference: "Psalm 37:11", text: "But the meek shall inherit the earth; and shall delight themselves in the abundance of peace." },
  { id: "peace-9", category: "peace", reference: "Psalm 37:37", text: "Mark the perfect man, and behold the upright: for the end of that man is peace." },
  { id: "peace-10", category: "peace", reference: "Psalm 85:8", text: "I will hear what God the Lord will speak: for he will speak peace unto his people, and to his saints: but let them not turn again to folly." },
  { id: "peace-11", category: "peace", reference: "Psalm 119:165", text: "Great peace have they which love thy law: and nothing shall offend them." },
  { id: "peace-12", category: "peace", reference: "Psalm 122:6-7", text: "Pray for the peace of Jerusalem: they shall prosper that love thee. Peace be within thy walls, and prosperity within thy palaces." },
  { id: "peace-13", category: "peace", reference: "Psalm 55:22", text: "Cast thy burden upon the Lord, and he shall sustain thee: he shall never suffer the righteous to be moved." },
  { id: "peace-14", category: "peace", reference: "Psalm 23:2-3", text: "He maketh me to lie down in green pastures: he leadeth me beside the still waters. He restoreth my soul: he leadeth me in the paths of righteousness for his name's sake." },
  { id: "peace-15", category: "peace", reference: "Psalm 94:19", text: "In the multitude of my thoughts within me thy comforts delight my soul." },
  { id: "peace-16", category: "peace", reference: "Psalm 62:1", text: "Truly my soul waiteth upon God: from him cometh my salvation." },
  { id: "peace-17", category: "peace", reference: "Psalm 46:10", text: "Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth." },
  { id: "peace-18", category: "peace", reference: "Psalm 131:2", text: "Surely I have behaved and quieted myself, as a child that is weaned of his mother: my soul is even as a weaned child." },
  { id: "peace-19", category: "peace", reference: "Proverbs 3:2", text: "For length of days, and long life, and peace, shall they add to thee." },
  { id: "peace-20", category: "peace", reference: "Proverbs 3:17", text: "Her ways are ways of pleasantness, and all her paths are peace." },
  { id: "peace-21", category: "peace", reference: "Proverbs 12:20", text: "Deceit is in the heart of them that imagine evil: but to the counsellors of peace is joy." },
  { id: "peace-22", category: "peace", reference: "Proverbs 16:7", text: "When a man's ways please the Lord, he maketh even his enemies to be at peace with him." },
  { id: "peace-23", category: "peace", reference: "Isaiah 9:6", text: "For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace." },
  { id: "peace-24", category: "peace", reference: "Isaiah 32:17-18", text: "And the work of righteousness shall be peace; and the effect of righteousness quietness and assurance for ever. And my people shall dwell in a peaceable habitation, and in sure dwellings, and in quiet resting places;" },
  { id: "peace-25", category: "peace", reference: "Isaiah 48:18", text: "O that thou hadst hearkened to my commandments! then had thy peace been as a river, and thy righteousness as the waves of the sea:" },
  { id: "peace-26", category: "peace", reference: "Isaiah 54:10", text: "For the mountains shall depart, and the hills be removed; but my kindness shall not depart from thee, neither shall the covenant of my peace be removed, saith the Lord that hath mercy on thee." },
  { id: "peace-27", category: "peace", reference: "Isaiah 54:13", text: "And all thy children shall be taught of the Lord; and great shall be the peace of thy children." },
  { id: "peace-28", category: "peace", reference: "Isaiah 55:12", text: "For ye shall go out with joy, and be led forth with peace: the mountains and the hills shall break forth before you into singing, and all the trees of the field shall clap their hands." },
  { id: "peace-29", category: "peace", reference: "Isaiah 57:19", text: "I create the fruit of the lips; Peace, peace to him that is far off, and to him that is near, saith the Lord; and I will heal him." },
  { id: "peace-30", category: "peace", reference: "Isaiah 66:12", text: "For thus saith the Lord, Behold, I will extend peace to her like a river, and the glory of the Gentiles like a flowing stream: then shall ye suck, ye shall be borne upon her sides, and be dandled upon her knees." },
  { id: "peace-31", category: "peace", reference: "Jeremiah 29:7", text: "And seek the peace of the city whither I have caused you to be carried away captives, and pray unto the Lord for it: for in the peace thereof shall ye have peace." },
  { id: "peace-32", category: "peace", reference: "Micah 5:5", text: "And this man shall be the peace, when the Assyrian shall come into our land: and when he shall tread in our palaces, then shall we raise against him seven shepherds, and eight principal men." },
  { id: "peace-33", category: "peace", reference: "Haggai 2:9", text: "The glory of this latter house shall be greater than of the former, saith the Lord of hosts: and in this place will I give peace, saith the Lord of hosts." },
  { id: "peace-34", category: "peace", reference: "Luke 1:79", text: "To give light to them that sit in darkness and in the shadow of death, to guide our feet into the way of peace." },
  { id: "peace-35", category: "peace", reference: "Luke 2:14", text: "Glory to God in the highest, and on earth peace, good will toward men." },
  { id: "peace-36", category: "peace", reference: "Luke 24:36", text: "And as they thus spake, Jesus himself stood in the midst of them, and saith unto them, Peace be unto you." },
  { id: "peace-37", category: "peace", reference: "John 14:1", text: "Let not your heart be troubled: ye believe in God, believe also in me." },
  { id: "peace-38", category: "peace", reference: "Romans 8:6", text: "For to be carnally minded is death; but to be spiritually minded is life and peace." },
  { id: "peace-39", category: "peace", reference: "Romans 12:18", text: "If it be possible, as much as lieth in you, live peaceably with all men." },
  { id: "peace-40", category: "peace", reference: "Romans 14:19", text: "Let us therefore follow after the things which make for peace, and things wherewith one may edify another." },
  { id: "peace-41", category: "peace", reference: "Romans 15:13", text: "Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost." },
  { id: "peace-42", category: "peace", reference: "1 Corinthians 14:33", text: "For God is not the author of confusion, but of peace, as in all churches of the saints." },
  { id: "peace-43", category: "peace", reference: "2 Corinthians 13:11", text: "Finally, brethren, farewell. Be perfect, be of good comfort, be of one mind, live in peace; and the God of love and peace shall be with you." },
  { id: "peace-44", category: "peace", reference: "Galatians 5:22-23", text: "But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, Meekness, temperance: against such there is no law." },
  { id: "peace-45", category: "peace", reference: "Ephesians 2:14", text: "For he is our peace, who hath made both one, and hath broken down the middle wall of partition between us;" },
  { id: "peace-46", category: "peace", reference: "Ephesians 4:3", text: "Endeavouring to keep the unity of the Spirit in the bond of peace." },
  { id: "peace-47", category: "peace", reference: "Colossians 3:15", text: "And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful." },
  { id: "peace-48", category: "peace", reference: "2 Thessalonians 3:16", text: "Now the Lord of peace himself give you peace always by all means. The Lord be with you all." },
  { id: "peace-49", category: "peace", reference: "Hebrews 12:14", text: "Follow peace with all men, and holiness, without which no man shall see the Lord:" },
  { id: "peace-50", category: "peace", reference: "1 Peter 3:11", text: "Let him eschew evil, and do good; let him seek peace, and ensue it." },
  { id: "provision-5", category: "provision", reference: "Genesis 22:14", text: "And Abraham called the name of that place Jehovahjireh: as it is said to this day, In the mount of the Lord it shall be seen." },
  { id: "provision-6", category: "provision", reference: "Genesis 26:12", text: "Then Isaac sowed in that land, and received in the same year an hundredfold: and the Lord blessed him." },
  { id: "provision-7", category: "provision", reference: "Deuteronomy 8:18", text: "But thou shalt remember the Lord thy God: for it is he that giveth thee power to get wealth, that he may establish his covenant which he sware unto thy fathers, as it is this day." },
  { id: "provision-8", category: "provision", reference: "Deuteronomy 28:12", text: "The Lord shall open unto thee his good treasure, the heaven to give the rain unto thy land in his season, and to bless all the work of thine hand: and thou shalt lend unto many nations, and thou shalt not borrow." },
  { id: "provision-9", category: "provision", reference: "Deuteronomy 2:7", text: "For the Lord thy God hath blessed thee in all the works of thy hand: he knoweth thy walking through this great wilderness: these forty years the Lord thy God hath been with thee; thou hast lacked nothing." },
  { id: "provision-10", category: "provision", reference: "1 Kings 17:14", text: "For thus saith the Lord God of Israel, The barrel of meal shall not waste, neither shall the cruse of oil fail, until the day that the Lord sendeth rain upon the earth." },
  { id: "provision-11", category: "provision", reference: "Psalm 23:5", text: "Thou preparest a table before me in the presence of mine enemies: thou anointest my head with oil; my cup runneth over." },
  { id: "provision-12", category: "provision", reference: "Psalm 34:10", text: "The young lions do lack, and suffer hunger: but they that seek the Lord shall not want any good thing." },
  { id: "provision-13", category: "provision", reference: "Psalm 37:3-4", text: "Trust in the Lord, and do good; so shalt thou dwell in the land, and verily thou shalt be fed. Delight thyself also in the Lord: and he shall give thee the desires of thine heart." },
  { id: "provision-14", category: "provision", reference: "Psalm 37:25", text: "I have been young, and now am old; yet have I not seen the righteous forsaken, nor his seed begging bread." },
  { id: "provision-15", category: "provision", reference: "Psalm 84:11", text: "For the Lord God is a sun and shield: the Lord will give grace and glory: no good thing will he withhold from them that walk uprightly." },
  { id: "provision-16", category: "provision", reference: "Psalm 81:10", text: "I am the Lord thy God, which brought thee out of the land of Egypt: open thy mouth wide, and I will fill it." },
  { id: "provision-17", category: "provision", reference: "Psalm 107:9", text: "For he satisfieth the longing soul, and filleth the hungry soul with goodness." },
  { id: "provision-18", category: "provision", reference: "Psalm 111:5", text: "He hath given meat unto them that fear him: he will ever be mindful of his covenant." },
  { id: "provision-19", category: "provision", reference: "Psalm 145:15-16", text: "The eyes of all wait upon thee; and thou givest them their meat in due season. Thou openest thine hand, and satisfiest the desire of every living thing." },
  { id: "provision-20", category: "provision", reference: "Psalm 132:15", text: "I will abundantly bless her provision: I will satisfy her poor with bread." },
  { id: "provision-21", category: "provision", reference: "Psalm 65:11", text: "Thou crownest the year with thy goodness; and thy paths drop fatness." },
  { id: "provision-22", category: "provision", reference: "Proverbs 3:9-10", text: "Honour the Lord with thy substance, and with the firstfruits of all thine increase: So shall thy barns be filled with plenty, and thy presses shall burst out with new wine." },
  { id: "provision-23", category: "provision", reference: "Proverbs 10:22", text: "The blessing of the Lord, it maketh rich, and he addeth no sorrow with it." },
  { id: "provision-24", category: "provision", reference: "Proverbs 11:24-25", text: "There is that scattereth, and yet increaseth; and there is that withholdeth more than is meet, but it tendeth to poverty. The liberal soul shall be made fat: and he that watereth shall be watered also himself." },
  { id: "provision-25", category: "provision", reference: "Proverbs 13:22", text: "A good man leaveth an inheritance to his children's children: and the wealth of the sinner is laid up for the just." },
  { id: "provision-26", category: "provision", reference: "Proverbs 22:9", text: "He that hath a bountiful eye shall be blessed; for he giveth of his bread to the poor." },
  { id: "provision-27", category: "provision", reference: "Proverbs 10:4", text: "He becometh poor that dealeth with a slack hand: but the hand of the diligent maketh rich." },
  { id: "provision-28", category: "provision", reference: "Proverbs 21:5", text: "The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want." },
  { id: "provision-29", category: "provision", reference: "Isaiah 1:19", text: "If ye be willing and obedient, ye shall eat the good of the land:" },
  { id: "provision-30", category: "provision", reference: "Isaiah 58:11", text: "And the Lord shall guide thee continually, and satisfy thy soul in drought, and make fat thy bones: and thou shalt be like a watered garden, and like a spring of water, whose waters fail not." },
  { id: "provision-31", category: "provision", reference: "Isaiah 65:24", text: "And it shall come to pass, that before they call, I will answer; and while they are yet speaking, I will hear." },
  { id: "provision-32", category: "provision", reference: "Joel 2:26", text: "And ye shall eat in plenty, and be satisfied, and praise the name of the Lord your God, that hath dealt wondrously with you: and my people shall never be ashamed." },
  { id: "provision-33", category: "provision", reference: "Haggai 2:8", text: "The silver is mine, and the gold is mine, saith the Lord of hosts." },
  { id: "provision-34", category: "provision", reference: "Malachi 3:11", text: "And I will rebuke the devourer for your sakes, and he shall not destroy the fruits of your ground; neither shall your vine cast her fruit before the time in the field, saith the Lord of hosts." },
  { id: "provision-35", category: "provision", reference: "Matthew 6:26", text: "Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?" },
  { id: "provision-36", category: "provision", reference: "Matthew 6:31-32", text: "Therefore take no thought, saying, What shall we eat? or, What shall we drink? or, Wherewithal shall we be clothed? (For after all these things do the Gentiles seek:) for your heavenly Father knoweth that ye have need of all these things." },
  { id: "provision-37", category: "provision", reference: "Matthew 7:11", text: "If ye then, being evil, know how to give good gifts unto your children, how much more shall your Father which is in heaven give good things to them that ask him?" },
  { id: "provision-38", category: "provision", reference: "Luke 6:38", text: "Give, and it shall be given unto you; good measure, pressed down, and shaken together, and running over, shall men give into your bosom. For with the same measure that ye mete withal it shall be measured to you again." },
  { id: "provision-39", category: "provision", reference: "Luke 12:24", text: "Consider the ravens: for they neither sow nor reap; which neither have storehouse nor barn; and God feedeth them: how much more are ye better than the fowls?" },
  { id: "provision-40", category: "provision", reference: "Luke 12:32", text: "Fear not, little flock; for it is your Father's good pleasure to give you the kingdom." },
  { id: "provision-41", category: "provision", reference: "John 10:10", text: "The thief cometh not, but for to steal, and to kill, and to destroy: I am come that they might have life, and that they might have it more abundantly." },
  { id: "provision-42", category: "provision", reference: "2 Corinthians 9:6", text: "But this I say, He which soweth sparingly shall reap also sparingly; and he which soweth bountifully shall reap also bountifully." },
  { id: "provision-43", category: "provision", reference: "2 Corinthians 9:8", text: "And God is able to make all grace abound toward you; that ye, always having all sufficiency in all things, may abound to every good work:" },
  { id: "provision-44", category: "provision", reference: "2 Corinthians 9:10-11", text: "Now he that ministereth seed to the sower both minister bread for your food, and multiply your seed sown, and increase the fruits of your righteousness;) Being enriched in every thing to all bountifulness, which causeth through us thanksgiving to God." },
  { id: "provision-45", category: "provision", reference: "2 Corinthians 8:9", text: "For ye know the grace of our Lord Jesus Christ, that, though he was rich, yet for your sakes he became poor, that ye through his poverty might be rich." },
  { id: "provision-46", category: "provision", reference: "1 Timothy 6:17", text: "Charge them that are rich in this world, that they be not highminded, nor trust in uncertain riches, but in the living God, who giveth us richly all things to enjoy;" },
  { id: "provision-47", category: "provision", reference: "Hebrews 13:5", text: "Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee." },
  { id: "provision-48", category: "provision", reference: "Romans 8:32", text: "He that spared not his own Son, but delivered him up for us all, how shall he not with him also freely give us all things?" },
  { id: "provision-49", category: "provision", reference: "Ephesians 3:20", text: "Now unto him that is able to do exceeding abundantly above all that we ask or think, according to the power that worketh in us," },
  { id: "provision-50", category: "provision", reference: "Jeremiah 29:11", text: "For I know the thoughts that I think toward you, saith the Lord, thoughts of peace, and not of evil, to give you an expected end." },
  { id: "wisdom-5", category: "wisdom", reference: "Proverbs 1:7", text: "The fear of the Lord is the beginning of knowledge: but fools despise wisdom and instruction." },
  { id: "wisdom-6", category: "wisdom", reference: "Proverbs 2:2-5", text: "So that thou incline thine ear unto wisdom, and apply thine heart to understanding; Yea, if thou criest after knowledge, and liftest up thy voice for understanding; If thou seekest her as silver, and searchest for her as for hid treasures; Then shalt thou understand the fear of the Lord, and find the knowledge of God." },
  { id: "wisdom-7", category: "wisdom", reference: "Proverbs 3:13-14", text: "Happy is the man that findeth wisdom, and the man that getteth understanding. For the merchandise of it is better than the merchandise of silver, and the gain thereof than fine gold." },
  { id: "wisdom-8", category: "wisdom", reference: "Proverbs 3:7", text: "Be not wise in thine own eyes: fear the Lord, and depart from evil." },
  { id: "wisdom-9", category: "wisdom", reference: "Proverbs 4:5-7", text: "Get wisdom, get understanding: forget it not; neither decline from the words of my mouth. Forsake her not, and she shall preserve thee: love her, and she shall keep thee. Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding." },
  { id: "wisdom-10", category: "wisdom", reference: "Proverbs 4:23", text: "Keep thy heart with all diligence; for out of it are the issues of life." },
  { id: "wisdom-11", category: "wisdom", reference: "Proverbs 8:11", text: "For wisdom is better than rubies; and all the things that may be desired are not to be compared to it." },
  { id: "wisdom-12", category: "wisdom", reference: "Proverbs 8:17", text: "I love them that love me; and those that seek me early shall find me." },
  { id: "wisdom-13", category: "wisdom", reference: "Proverbs 9:10", text: "The fear of the Lord is the beginning of wisdom: and the knowledge of the holy is understanding." },
  { id: "wisdom-14", category: "wisdom", reference: "Proverbs 11:2", text: "When pride cometh, then cometh shame: but with the lowly is wisdom." },
  { id: "wisdom-15", category: "wisdom", reference: "Proverbs 11:14", text: "Where no counsel is, the people fall: but in the multitude of counsellors there is safety." },
  { id: "wisdom-16", category: "wisdom", reference: "Proverbs 12:15", text: "The way of a fool is right in his own eyes: but he that hearkeneth unto counsel is wise." },
  { id: "wisdom-17", category: "wisdom", reference: "Proverbs 13:20", text: "He that walketh with wise men shall be wise: but a companion of fools shall be destroyed." },
  { id: "wisdom-18", category: "wisdom", reference: "Proverbs 15:22", text: "Without counsel purposes are disappointed: but in the multitude of counsellors they are established." },
  { id: "wisdom-19", category: "wisdom", reference: "Proverbs 15:33", text: "The fear of the Lord is the instruction of wisdom; and before honour is humility." },
  { id: "wisdom-20", category: "wisdom", reference: "Proverbs 16:3", text: "Commit thy works unto the Lord, and thy thoughts shall be established." },
  { id: "wisdom-21", category: "wisdom", reference: "Proverbs 16:9", text: "A man's heart deviseth his way: but the Lord directeth his steps." },
  { id: "wisdom-22", category: "wisdom", reference: "Proverbs 16:16", text: "How much better is it to get wisdom than gold! and to get understanding rather to be chosen than silver!" },
  { id: "wisdom-23", category: "wisdom", reference: "Proverbs 18:15", text: "The heart of the prudent getteth knowledge; and the ear of the wise seeketh knowledge." },
  { id: "wisdom-24", category: "wisdom", reference: "Proverbs 19:20-21", text: "Hear counsel, and receive instruction, that thou mayest be wise in thy latter end. There are many devices in a man's heart; nevertheless the counsel of the Lord, that shall stand." },
  { id: "wisdom-25", category: "wisdom", reference: "Proverbs 24:3-4", text: "Through wisdom is an house builded; and by understanding it is established: And by knowledge shall the chambers be filled with all precious and pleasant riches." },
  { id: "wisdom-26", category: "wisdom", reference: "Proverbs 27:17", text: "Iron sharpeneth iron; so a man sharpeneth the countenance of his friend." },
  { id: "wisdom-27", category: "wisdom", reference: "Psalm 19:7", text: "The law of the Lord is perfect, converting the soul: the testimony of the Lord is sure, making wise the simple." },
  { id: "wisdom-28", category: "wisdom", reference: "Psalm 25:4-5", text: "Shew me thy ways, O Lord; teach me thy paths. Lead me in thy truth, and teach me: for thou art the God of my salvation; on thee do I wait all the day." },
  { id: "wisdom-29", category: "wisdom", reference: "Psalm 32:8", text: "I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye." },
  { id: "wisdom-30", category: "wisdom", reference: "Psalm 111:10", text: "The fear of the Lord is the beginning of wisdom: a good understanding have all they that do his commandments: his praise endureth for ever." },
  { id: "wisdom-31", category: "wisdom", reference: "Psalm 119:11", text: "Thy word have I hid in mine heart, that I might not sin against thee." },
  { id: "wisdom-32", category: "wisdom", reference: "Psalm 119:130", text: "The entrance of thy words giveth light; it giveth understanding unto the simple." },
  { id: "wisdom-33", category: "wisdom", reference: "Psalm 90:12", text: "So teach us to number our days, that we may apply our hearts unto wisdom." },
  { id: "wisdom-34", category: "wisdom", reference: "Daniel 2:20-21", text: "Daniel answered and said, Blessed be the name of God for ever and ever: for wisdom and might are his: And he changeth the times and the seasons: he removeth kings, and setteth up kings: he giveth wisdom unto the wise, and knowledge to them that know understanding:" },
  { id: "wisdom-35", category: "wisdom", reference: "Daniel 12:3", text: "And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever." },
  { id: "wisdom-36", category: "wisdom", reference: "James 3:17", text: "But the wisdom that is from above is first pure, then peaceable, gentle, and easy to be intreated, full of mercy and good fruits, without partiality, and without hypocrisy." },
  { id: "wisdom-37", category: "wisdom", reference: "Colossians 2:3", text: "In whom are hid all the treasures of wisdom and knowledge." },
  { id: "wisdom-38", category: "wisdom", reference: "Colossians 3:16", text: "Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord." },
  { id: "wisdom-39", category: "wisdom", reference: "Colossians 1:9-10", text: "For this cause we also, since the day we heard it, do not cease to pray for you, and to desire that ye might be filled with the knowledge of his will in all wisdom and spiritual understanding; That ye might walk worthy of the Lord unto all pleasing, being fruitful in every good work, and increasing in the knowledge of God;" },
  { id: "wisdom-40", category: "wisdom", reference: "Ephesians 1:17", text: "That the God of our Lord Jesus Christ, the Father of glory, may give unto you the spirit of wisdom and revelation in the knowledge of him:" },
  { id: "wisdom-41", category: "wisdom", reference: "Ephesians 5:15-16", text: "See then that ye walk circumspectly, not as fools, but as wise, Redeeming the time, because the days are evil." },
  { id: "wisdom-42", category: "wisdom", reference: "1 Corinthians 1:30", text: "But of him are ye in Christ Jesus, who of God is made unto us wisdom, and righteousness, and sanctification, and redemption:" },
  { id: "wisdom-43", category: "wisdom", reference: "Job 28:28", text: "And unto man he said, Behold, the fear of the Lord, that is wisdom; and to depart from evil is understanding." },
  { id: "wisdom-44", category: "wisdom", reference: "Isaiah 11:2", text: "And the spirit of the Lord shall rest upon him, the spirit of wisdom and understanding, the spirit of counsel and might, the spirit of knowledge and of the fear of the Lord;" },
  { id: "wisdom-45", category: "wisdom", reference: "Isaiah 30:21", text: "And thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left." },
  { id: "wisdom-46", category: "wisdom", reference: "Isaiah 33:6", text: "And wisdom and knowledge shall be the stability of thy times, and strength of salvation: the fear of the Lord is his treasure." },
  { id: "wisdom-47", category: "wisdom", reference: "Luke 2:52", text: "And Jesus increased in wisdom and stature, and in favour with God and man." },
  { id: "wisdom-48", category: "wisdom", reference: "Matthew 7:24", text: "Therefore whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man, which built his house upon a rock:" },
  { id: "wisdom-49", category: "wisdom", reference: "Romans 11:33", text: "O the depth of the riches both of the wisdom and knowledge of God! how unsearchable are his judgments, and his ways past finding out!" },
  { id: "wisdom-50", category: "wisdom", reference: "Romans 12:2", text: "And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God." },
  { id: "prayer-6", category: "prayer", reference: "Psalm 5:3", text: "My voice shalt thou hear in the morning, O Lord; in the morning will I direct my prayer unto thee, and will look up." },
  { id: "prayer-7", category: "prayer", reference: "Psalm 17:6", text: "I have called upon thee, for thou wilt hear me, O God: incline thine ear unto me, and hear my speech." },
  { id: "prayer-8", category: "prayer", reference: "Psalm 34:15", text: "The eyes of the Lord are upon the righteous, and his ears are open unto their cry." },
  { id: "prayer-9", category: "prayer", reference: "Psalm 34:17", text: "The righteous cry, and the Lord heareth, and delivereth them out of all their troubles." },
  { id: "prayer-10", category: "prayer", reference: "Psalm 55:17", text: "Evening, and morning, and at noon, will I pray, and cry aloud: and he shall hear my voice." },
  { id: "prayer-11", category: "prayer", reference: "Psalm 66:18-19", text: "If I regard iniquity in my heart, the Lord will not hear me: But verily God hath heard me; he hath attended to the voice of my prayer." },
  { id: "prayer-12", category: "prayer", reference: "Psalm 86:5-7", text: "For thou, Lord, art good, and ready to forgive; and plenteous in mercy unto all them that call upon thee. Give ear, O Lord, unto my prayer; and attend to the voice of my supplications. In the day of my trouble I will call upon thee: for thou wilt answer me." },
  { id: "prayer-13", category: "prayer", reference: "Psalm 102:17", text: "He will regard the prayer of the destitute, and not despise their prayer." },
  { id: "prayer-14", category: "prayer", reference: "Psalm 116:1-2", text: "I love the Lord, because he hath heard my voice and my supplications. Because he hath inclined his ear unto me, therefore will I call upon him as long as I live." },
  { id: "prayer-15", category: "prayer", reference: "Psalm 141:2", text: "Let my prayer be set forth before thee as incense; and the lifting up of my hands as the evening sacrifice." },
  { id: "prayer-16", category: "prayer", reference: "Psalm 145:18", text: "The Lord is nigh unto all them that call upon him, to all that call upon him in truth." },
  { id: "prayer-17", category: "prayer", reference: "Psalm 50:15", text: "And call upon me in the day of trouble: I will deliver thee, and thou shalt glorify me." },
  { id: "prayer-18", category: "prayer", reference: "Psalm 62:8", text: "Trust in him at all times; ye people, pour out your heart before him: God is a refuge for us. Selah." },
  { id: "prayer-19", category: "prayer", reference: "Psalm 4:3", text: "But know that the Lord hath set apart him that is godly for himself: the Lord will hear when I call unto him." },
  { id: "prayer-20", category: "prayer", reference: "Psalm 40:1", text: "I waited patiently for the Lord; and he inclined unto me, and heard my cry." },
  { id: "prayer-21", category: "prayer", reference: "1 Chronicles 4:10", text: "And Jabez called on the God of Israel, saying, Oh that thou wouldest bless me indeed, and enlarge my coast, and that thine hand might be with me, and that thou wouldest keep me from evil, that it may not grieve me! And God granted him that which he requested." },
  { id: "prayer-22", category: "prayer", reference: "Isaiah 58:9", text: "Then shalt thou call, and the Lord shall answer; thou shalt cry, and he shall say, Here I am. If thou take away from the midst of thee the yoke, the putting forth of the finger, and speaking vanity;" },
  { id: "prayer-23", category: "prayer", reference: "Isaiah 59:1", text: "Behold, the Lord's hand is not shortened, that it cannot save; neither his ear heavy, that it cannot hear:" },
  { id: "prayer-24", category: "prayer", reference: "Isaiah 56:7", text: "Even them will I bring to my holy mountain, and make them joyful in my house of prayer: their burnt offerings and their sacrifices shall be accepted upon mine altar; for mine house shall be called an house of prayer for all people." },
  { id: "prayer-25", category: "prayer", reference: "Isaiah 55:6", text: "Seek ye the Lord while he may be found, call ye upon him while he is near:" },
  { id: "prayer-26", category: "prayer", reference: "Jeremiah 29:12-13", text: "Then shall ye call upon me, and ye shall go and pray unto me, and I will hearken unto you. And ye shall seek me, and find me, when ye shall search for me with all your heart." },
  { id: "prayer-27", category: "prayer", reference: "Matthew 6:6", text: "But thou, when thou prayest, enter into thy closet, and when thou hast shut thy door, pray to thy Father which is in secret; and thy Father which seeth in secret shall reward thee openly." },
  { id: "prayer-28", category: "prayer", reference: "Matthew 6:9-13", text: "After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name. Thy kingdom come, Thy will be done in earth, as it is in heaven. Give us this day our daily bread. And forgive us our debts, as we forgive our debtors. And lead us not into temptation, but deliver us from evil: For thine is the kingdom, and the power, and the glory, for ever. Amen." },
  { id: "prayer-29", category: "prayer", reference: "Matthew 21:22", text: "And all things, whatsoever ye shall ask in prayer, believing, ye shall receive." },
  { id: "prayer-30", category: "prayer", reference: "Matthew 26:41", text: "Watch and pray, that ye enter not into temptation: the spirit indeed is willing, but the flesh is weak." },
  { id: "prayer-31", category: "prayer", reference: "Mark 1:35", text: "And in the morning, rising up a great while before day, he went out, and departed into a solitary place, and there prayed." },
  { id: "prayer-32", category: "prayer", reference: "Mark 11:25", text: "And when ye stand praying, forgive, if ye have ought against any: that your Father also which is in heaven may forgive you your trespasses." },
  { id: "prayer-33", category: "prayer", reference: "Luke 11:9-10", text: "And I say unto you, Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you. For every one that asketh receiveth; and he that seeketh findeth; and to him that knocketh it shall be opened." },
  { id: "prayer-34", category: "prayer", reference: "Luke 18:1", text: "And he spake a parable unto them to this end, that men ought always to pray, and not to faint;" },
  { id: "prayer-35", category: "prayer", reference: "Luke 11:13", text: "If ye then, being evil, know how to give good gifts unto your children: how much more shall your heavenly Father give the Holy Spirit to them that ask him?" },
  { id: "prayer-36", category: "prayer", reference: "Luke 5:16", text: "And he withdrew himself into the wilderness, and prayed." },
  { id: "prayer-37", category: "prayer", reference: "Luke 6:12", text: "And it came to pass in those days, that he went out into a mountain to pray, and continued all night in prayer to God." },
  { id: "prayer-38", category: "prayer", reference: "John 14:13-14", text: "And whatsoever ye shall ask in my name, that will I do, that the Father may be glorified in the Son. If ye shall ask any thing in my name, I will do it." },
  { id: "prayer-39", category: "prayer", reference: "John 15:7", text: "If ye abide in me, and my words abide in you, ye shall ask what ye will, and it shall be done unto you." },
  { id: "prayer-40", category: "prayer", reference: "John 15:16", text: "Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you." },
  { id: "prayer-41", category: "prayer", reference: "John 16:24", text: "Hitherto have ye asked nothing in my name: ask, and ye shall receive, that your joy may be full." },
  { id: "prayer-42", category: "prayer", reference: "Acts 1:14", text: "These all continued with one accord in prayer and supplication, with the women, and Mary the mother of Jesus, and with his brethren." },
  { id: "prayer-43", category: "prayer", reference: "Acts 2:42", text: "And they continued stedfastly in the apostles' doctrine and fellowship, and in breaking of bread, and in prayers." },
  { id: "prayer-44", category: "prayer", reference: "Acts 4:31", text: "And when they had prayed, the place was shaken where they were assembled together; and they were all filled with the Holy Ghost, and they spake the word of God with boldness." },
  { id: "prayer-45", category: "prayer", reference: "Acts 12:5", text: "Peter therefore was kept in prison: but prayer was made without ceasing of the church unto God for him." },
  { id: "prayer-46", category: "prayer", reference: "Romans 8:26", text: "Likewise the Spirit also helpeth our infirmities: for we know not what we should pray for as we ought: but the Spirit itself maketh intercession for us with groanings which cannot be uttered." },
  { id: "prayer-47", category: "prayer", reference: "Romans 12:12", text: "Rejoicing in hope; patient in tribulation; continuing instant in prayer;" },
  { id: "prayer-48", category: "prayer", reference: "Ephesians 6:18", text: "Praying always with all prayer and supplication in the Spirit, and watching thereunto with all perseverance and supplication for all saints;" },
  { id: "prayer-49", category: "prayer", reference: "Colossians 4:2", text: "Continue in prayer, and watch in the same with thanksgiving;" },
  { id: "prayer-50", category: "prayer", reference: "1 Timothy 2:1", text: "I exhort therefore, that, first of all, supplications, prayers, intercessions, and giving of thanks, be made for all men;" },
  { id: "family-5", category: "family", reference: "Genesis 2:24", text: "Therefore shall a man leave his father and his mother, and shall cleave unto his wife: and they shall be one flesh." },
  { id: "family-6", category: "family", reference: "Genesis 18:19", text: "For I know him, that he will command his children and his household after him, and they shall keep the way of the Lord, to do justice and judgment; that the Lord may bring upon Abraham that which he hath spoken of him." },
  { id: "family-7", category: "family", reference: "Exodus 20:12", text: "Honour thy father and thy mother: that thy days may be long upon the land which the Lord thy God giveth thee." },
  { id: "family-8", category: "family", reference: "Deuteronomy 6:6-7", text: "And these words, which I command thee this day, shall be in thine heart: And thou shalt teach them diligently unto thy children, and shalt talk of them when thou sittest in thine house, and when thou walkest by the way, and when thou liest down, and when thou risest up." },
  { id: "family-9", category: "family", reference: "Deuteronomy 5:16", text: "Honour thy father and thy mother, as the Lord thy God hath commanded thee; that thy days may be prolonged, and that it may go well with thee, in the land which the Lord thy God giveth thee." },
  { id: "family-10", category: "family", reference: "Deuteronomy 11:19", text: "And ye shall teach them your children, speaking of them when thou sittest in thine house, and when thou walkest by the way, when thou liest down, and when thou risest up." },
  { id: "family-11", category: "family", reference: "Ruth 1:16", text: "And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:" },
  { id: "family-12", category: "family", reference: "1 Samuel 1:27", text: "For this child I prayed; and the Lord hath given me my petition which I asked of him:" },
  { id: "family-13", category: "family", reference: "Psalm 68:6", text: "God setteth the solitary in families: he bringeth out those which are bound with chains: but the rebellious dwell in a dry land." },
  { id: "family-14", category: "family", reference: "Psalm 78:4", text: "We will not hide them from their children, shewing to the generation to come the praises of the Lord, and his strength, and his wonderful works that he hath done." },
  { id: "family-15", category: "family", reference: "Psalm 103:13", text: "Like as a father pitieth his children, so the Lord pitieth them that fear him." },
  { id: "family-16", category: "family", reference: "Psalm 103:17", text: "But the mercy of the Lord is from everlasting to everlasting upon them that fear him, and his righteousness unto children's children;" },
  { id: "family-17", category: "family", reference: "Psalm 112:1-2", text: "Praise ye the Lord. Blessed is the man that feareth the Lord, that delighteth greatly in his commandments. His seed shall be mighty upon earth: the generation of the upright shall be blessed." },
  { id: "family-18", category: "family", reference: "Psalm 127:1", text: "Except the Lord build the house, they labour in vain that build it: except the Lord keep the city, the watchman waketh but in vain." },
  { id: "family-19", category: "family", reference: "Psalm 127:4-5", text: "As arrows are in the hand of a mighty man; so are children of the youth. Happy is the man that hath his quiver full of them: they shall not be ashamed, but they shall speak with the enemies in the gate." },
  { id: "family-20", category: "family", reference: "Psalm 128:1-3", text: "Blessed is every one that feareth the Lord; that walketh in his ways. For thou shalt eat the labour of thine hands: happy shalt thou be, and it shall be well with thee. Thy wife shall be as a fruitful vine by the sides of thine house: thy children like olive plants round about thy table." },
  { id: "family-21", category: "family", reference: "Psalm 133:1", text: "Behold, how good and how pleasant it is for brethren to dwell together in unity!" },
  { id: "family-22", category: "family", reference: "Psalm 145:4", text: "One generation shall praise thy works to another, and shall declare thy mighty acts." },
  { id: "family-23", category: "family", reference: "Proverbs 14:1", text: "Every wise woman buildeth her house: but the foolish plucketh it down with her hands." },
  { id: "family-24", category: "family", reference: "Proverbs 14:26", text: "In the fear of the Lord is strong confidence: and his children shall have a place of refuge." },
  { id: "family-25", category: "family", reference: "Proverbs 15:20", text: "A wise son maketh a glad father: but a foolish man despiseth his mother." },
  { id: "family-26", category: "family", reference: "Proverbs 17:6", text: "Children's children are the crown of old men; and the glory of children are their fathers." },
  { id: "family-27", category: "family", reference: "Proverbs 17:17", text: "A friend loveth at all times, and a brother is born for adversity." },
  { id: "family-28", category: "family", reference: "Proverbs 18:22", text: "Whoso findeth a wife findeth a good thing, and obtaineth favour of the Lord." },
  { id: "family-29", category: "family", reference: "Proverbs 19:14", text: "House and riches are the inheritance of fathers: and a prudent wife is from the Lord." },
  { id: "family-30", category: "family", reference: "Proverbs 20:7", text: "The just man walketh in his integrity: his children are blessed after him." },
  { id: "family-31", category: "family", reference: "Proverbs 23:24-25", text: "The father of the righteous shall greatly rejoice: and he that begetteth a wise child shall have joy of him. Thy father and thy mother shall be glad, and she that bare thee shall rejoice." },
  { id: "family-32", category: "family", reference: "Proverbs 29:17", text: "Correct thy son, and he shall give thee rest; yea, he shall give delight unto thy soul." },
  { id: "family-33", category: "family", reference: "Proverbs 31:10", text: "Who can find a virtuous woman? for her price is far above rubies." },
  { id: "family-34", category: "family", reference: "Proverbs 31:25-28", text: "Strength and honour are her clothing; and she shall rejoice in time to come. She openeth her mouth with wisdom; and in her tongue is the law of kindness. She looketh well to the ways of her household, and eateth not the bread of idleness. Her children arise up, and call her blessed; her husband also, and he praiseth her." },
  { id: "family-35", category: "family", reference: "Ecclesiastes 4:9-10", text: "Two are better than one; because they have a good reward for their labour. For if they fall, the one will lift up his fellow: but woe to him that is alone when he falleth; for he hath not another to help him up." },
  { id: "family-36", category: "family", reference: "Ecclesiastes 4:12", text: "And if one prevail against him, two shall withstand him; and a threefold cord is not quickly broken." },
  { id: "family-37", category: "family", reference: "Malachi 4:6", text: "And he shall turn the heart of the fathers to the children, and the heart of the children to their fathers, lest I come and smite the earth with a curse." },
  { id: "family-38", category: "family", reference: "Isaiah 59:21", text: "As for me, this is my covenant with them, saith the Lord; My spirit that is upon thee, and my words which I have put in thy mouth, shall not depart out of thy mouth, nor out of the mouth of thy seed, nor out of the mouth of thy seed's seed, saith the Lord, from henceforth and for ever." },
  { id: "family-39", category: "family", reference: "Matthew 19:5-6", text: "And said, For this cause shall a man leave father and mother, and shall cleave to his wife: and they twain shall be one flesh? Wherefore they are no more twain, but one flesh. What therefore God hath joined together, let not man put asunder." },
  { id: "family-40", category: "family", reference: "Matthew 19:14", text: "But Jesus said, Suffer little children, and forbid them not, to come unto me: for of such is the kingdom of heaven." },
  { id: "family-41", category: "family", reference: "Mark 10:14", text: "But when Jesus saw it, he was much displeased, and said unto them, Suffer the little children to come unto me, and forbid them not: for of such is the kingdom of God." },
  { id: "family-42", category: "family", reference: "Acts 2:39", text: "For the promise is unto you, and to your children, and to all that are afar off, even as many as the Lord our God shall call." },
  { id: "family-43", category: "family", reference: "Ephesians 5:25", text: "Husbands, love your wives, even as Christ also loved the church, and gave himself for it;" },
  { id: "family-44", category: "family", reference: "Ephesians 5:33", text: "Nevertheless let every one of you in particular so love his wife even as himself; and the wife see that she reverence her husband." },
  { id: "family-45", category: "family", reference: "Ephesians 6:1-3", text: "Children, obey your parents in the Lord: for this is right. Honour thy father and mother; which is the first commandment with promise; That it may be well with thee, and thou mayest live long on the earth." },
  { id: "family-46", category: "family", reference: "Ephesians 6:4", text: "And, ye fathers, provoke not your children to wrath: but bring them up in the nurture and admonition of the Lord." },
  { id: "family-47", category: "family", reference: "Colossians 3:18-21", text: "Wives, submit yourselves unto your own husbands, as it is fit in the Lord. Husbands, love your wives, and be not bitter against them. Children, obey your parents in all things: for this is well pleasing unto the Lord. Fathers, provoke not your children to anger, lest they be discouraged." },
  { id: "family-48", category: "family", reference: "1 Timothy 5:8", text: "But if any provide not for his own, and specially for those of his own house, he hath denied the faith, and is worse than an infidel." },
  { id: "family-49", category: "family", reference: "1 Timothy 3:4-5", text: "One that ruleth well his own house, having his children in subjection with all gravity; (For if a man know not how to rule his own house, how shall he take care of the church of God?)" },
  { id: "family-50", category: "family", reference: "1 Peter 3:7", text: "Likewise, ye husbands, dwell with them according to knowledge, giving honour unto the wife, as unto the weaker vessel, and as being heirs together of the grace of life; that your prayers be not hindered." },
  { id: "thanksgiving-5", category: "thanksgiving", reference: "Psalm 9:1", text: "I will praise thee, O Lord, with my whole heart; I will shew forth all thy marvellous works." },
  { id: "thanksgiving-6", category: "thanksgiving", reference: "Psalm 30:12", text: "To the end that my glory may sing praise to thee, and not be silent. O Lord my God, I will give thanks unto thee for ever." },
  { id: "thanksgiving-7", category: "thanksgiving", reference: "Psalm 34:1", text: "I will bless the Lord at all times: his praise shall continually be in my mouth." },
  { id: "thanksgiving-8", category: "thanksgiving", reference: "Psalm 35:18", text: "I will give thee thanks in the great congregation: I will praise thee among much people." },
  { id: "thanksgiving-9", category: "thanksgiving", reference: "Psalm 50:14", text: "Offer unto God thanksgiving; and pay thy vows unto the most High:" },
  { id: "thanksgiving-10", category: "thanksgiving", reference: "Psalm 69:30", text: "I will praise the name of God with a song, and will magnify him with thanksgiving." },
  { id: "thanksgiving-11", category: "thanksgiving", reference: "Psalm 75:1", text: "Unto thee, O God, do we give thanks, unto thee do we give thanks: for that thy name is near thy wondrous works declare." },
  { id: "thanksgiving-12", category: "thanksgiving", reference: "Psalm 92:1-2", text: "It is a good thing to give thanks unto the Lord, and to sing praises unto thy name, O Most High: To shew forth thy lovingkindness in the morning, and thy faithfulness every night," },
  { id: "thanksgiving-13", category: "thanksgiving", reference: "Psalm 95:2", text: "Let us come before his presence with thanksgiving, and make a joyful noise unto him with psalms." },
  { id: "thanksgiving-14", category: "thanksgiving", reference: "Psalm 100:1-3", text: "Make a joyful noise unto the Lord, all ye lands. Serve the Lord with gladness: come before his presence with singing. Know ye that the Lord he is God: it is he that hath made us, and not we ourselves; we are his people, and the sheep of his pasture." },
  { id: "thanksgiving-15", category: "thanksgiving", reference: "Psalm 103:1-2", text: "Bless the Lord, O my soul: and all that is within me, bless his holy name. Bless the Lord, O my soul, and forget not all his benefits:" },
  { id: "thanksgiving-16", category: "thanksgiving", reference: "Psalm 105:1", text: "O give thanks unto the Lord; call upon his name: make known his deeds among the people." },
  { id: "thanksgiving-17", category: "thanksgiving", reference: "Psalm 106:1", text: "Praise ye the Lord. O give thanks unto the Lord; for he is good: for his mercy endureth for ever." },
  { id: "thanksgiving-18", category: "thanksgiving", reference: "Psalm 107:8", text: "Oh that men would praise the Lord for his goodness, and for his wonderful works to the children of men!" },
  { id: "thanksgiving-19", category: "thanksgiving", reference: "Psalm 116:12-13", text: "What shall I render unto the Lord for all his benefits toward me? I will take the cup of salvation, and call upon the name of the Lord." },
  { id: "thanksgiving-20", category: "thanksgiving", reference: "Psalm 118:1", text: "O give thanks unto the Lord; for he is good: because his mercy endureth for ever." },
  { id: "thanksgiving-21", category: "thanksgiving", reference: "Psalm 118:24", text: "This is the day which the Lord hath made; we will rejoice and be glad in it." },
  { id: "thanksgiving-22", category: "thanksgiving", reference: "Psalm 119:62", text: "At midnight I will rise to give thanks unto thee because of thy righteous judgments." },
  { id: "thanksgiving-23", category: "thanksgiving", reference: "Psalm 136:1", text: "O give thanks unto the Lord; for he is good: for his mercy endureth for ever." },
  { id: "thanksgiving-24", category: "thanksgiving", reference: "Psalm 138:1", text: "I will praise thee with my whole heart: before the gods will I sing praise unto thee." },
  { id: "thanksgiving-25", category: "thanksgiving", reference: "Psalm 139:14", text: "I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well." },
  { id: "thanksgiving-26", category: "thanksgiving", reference: "Psalm 145:1-2", text: "I will extol thee, my God, O king; and I will bless thy name for ever and ever. Every day will I bless thee; and I will praise thy name for ever and ever." },
  { id: "thanksgiving-27", category: "thanksgiving", reference: "Psalm 147:7", text: "Sing unto the Lord with thanksgiving; sing praise upon the harp unto our God:" },
  { id: "thanksgiving-28", category: "thanksgiving", reference: "Psalm 150:6", text: "Let every thing that hath breath praise the Lord. Praise ye the Lord." },
  { id: "thanksgiving-29", category: "thanksgiving", reference: "Psalm 79:13", text: "So we thy people and sheep of thy pasture will give thee thanks for ever: we will shew forth thy praise to all generations." },
  { id: "thanksgiving-30", category: "thanksgiving", reference: "Psalm 86:12", text: "I will praise thee, O Lord my God, with all my heart: and I will glorify thy name for evermore." },
  { id: "thanksgiving-31", category: "thanksgiving", reference: "Psalm 111:1", text: "Praise ye the Lord. I will praise the Lord with my whole heart, in the assembly of the upright, and in the congregation." },
  { id: "thanksgiving-32", category: "thanksgiving", reference: "Psalm 126:3", text: "The Lord hath done great things for us; whereof we are glad." },
  { id: "thanksgiving-33", category: "thanksgiving", reference: "1 Chronicles 16:8", text: "Give thanks unto the Lord, call upon his name, make known his deeds among the people." },
  { id: "thanksgiving-34", category: "thanksgiving", reference: "1 Chronicles 16:34", text: "O give thanks unto the Lord; for he is good; for his mercy endureth for ever." },
  { id: "thanksgiving-35", category: "thanksgiving", reference: "1 Chronicles 29:13", text: "Now therefore, our God, we thank thee, and praise thy glorious name." },
  { id: "thanksgiving-36", category: "thanksgiving", reference: "2 Chronicles 20:21", text: "And when he had consulted with the people, he appointed singers unto the Lord, and that should praise the beauty of holiness, as they went out before the army, and to say, Praise the Lord; for his mercy endureth for ever." },
  { id: "thanksgiving-37", category: "thanksgiving", reference: "Ezra 3:11", text: "And they sang together by course in praising and giving thanks unto the Lord; because he is good, for his mercy endureth for ever toward Israel. And all the people shouted with a great shout, when they praised the Lord, because the foundation of the house of the Lord was laid." },
  { id: "thanksgiving-38", category: "thanksgiving", reference: "Jonah 2:9", text: "But I will sacrifice unto thee with the voice of thanksgiving; I will pay that that I have vowed. Salvation is of the Lord." },
  { id: "thanksgiving-39", category: "thanksgiving", reference: "Lamentations 3:22-23", text: "It is of the Lord's mercies that we are not consumed, because his compassions fail not. They are new every morning: great is thy faithfulness." },
  { id: "thanksgiving-40", category: "thanksgiving", reference: "Luke 17:16", text: "And fell down on his face at his feet, giving him thanks: and he was a Samaritan." },
  { id: "thanksgiving-41", category: "thanksgiving", reference: "2 Corinthians 9:15", text: "Thanks be unto God for his unspeakable gift." },
  { id: "thanksgiving-42", category: "thanksgiving", reference: "2 Corinthians 2:14", text: "Now thanks be unto God, which always causeth us to triumph in Christ, and maketh manifest the savour of his knowledge by us in every place." },
  { id: "thanksgiving-43", category: "thanksgiving", reference: "1 Corinthians 15:57", text: "But thanks be to God, which giveth us the victory through our Lord Jesus Christ." },
  { id: "thanksgiving-44", category: "thanksgiving", reference: "Ephesians 5:20", text: "Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ;" },
  { id: "thanksgiving-45", category: "thanksgiving", reference: "Ephesians 1:16", text: "Cease not to give thanks for you, making mention of you in my prayers;" },
  { id: "thanksgiving-46", category: "thanksgiving", reference: "Philippians 1:3", text: "I thank my God upon every remembrance of you," },
  { id: "thanksgiving-47", category: "thanksgiving", reference: "Colossians 2:7", text: "Rooted and built up in him, and stablished in the faith, as ye have been taught, abounding therein with thanksgiving." },
  { id: "thanksgiving-48", category: "thanksgiving", reference: "Hebrews 13:15", text: "By him therefore let us offer the sacrifice of praise to God continually, that is, the fruit of our lips giving thanks to his name." },
  { id: "thanksgiving-49", category: "thanksgiving", reference: "1 Timothy 4:4-5", text: "For every creature of God is good, and nothing to be refused, if it be received with thanksgiving: For it is sanctified by the word of God and prayer." },
  { id: "thanksgiving-50", category: "thanksgiving", reference: "Revelation 7:12", text: "Saying, Amen: Blessing, and glory, and wisdom, and thanksgiving, and honour, and power, and might, be unto our God for ever and ever. Amen." },
];
